importScripts('vendor/cv.js','vendor/aruco.js','planar-tracking.js','ar-features.js');
// Primary tracking: ~2000 natural feature points from the printed poster (assets/poster-features.bin).
// The four corner markers remain a fallback and can seed feature tracking.
let features=null,featuresSettled=!self.fetch;
const featuresReady=(self.fetch?fetch('assets/poster-features.bin').then(r=>{if(!r.ok)throw new Error('features '+r.status);return r.arrayBuffer();}):Promise.reject(new Error('fetch unavailable'))).then(b=>{features=PosterFeatures.createTracker(PosterFeatures.deserialize(b));}).catch(()=>{features=null;}).then(()=>{featuresSettled=true;});
self.posterFeaturesReady=featuresReady;
// The dictionary has minimum distance 12; correct up to 3 bits, then verify page geometry.
// This library uses an exclusive error threshold.
const detector=new AR.Detector({dictionaryName:'ARUCO_MIP_36h12',maxHammingDistance:4});
// 8x8 markers need an integer number of sampling pixels per cell.
const findMarkers=detector.findMarkers;
detector.findMarkers=function(grey,candidates){return findMarkers.call(this,grey,candidates,80);};
const expected=new Set([0,7,2,3]);
let previous=null;
function cropScaled(image,x0,y0,w,h,scale){const outW=Math.round(w*scale),outH=Math.round(h*scale),out=new Uint8ClampedArray(outW*outH*4);for(let y=0;y<outH;y++){const sy=Math.min(image.height-1,y0+Math.floor(y/scale));for(let x=0;x<outW;x++){const sx=Math.min(image.width-1,x0+Math.floor(x/scale)),i=(sy*image.width+sx)*4,j=(y*outW+x)*4;out[j]=image.data[i];out[j+1]=image.data[i+1];out[j+2]=image.data[i+2];out[j+3]=255;}}return {width:outW,height:outH,data:out};}
function trackedRegions(image){if(!previous||previous.width!==image.width||previous.height!==image.height)return [];const found=[];for(const [idString,origin] of Object.entries(PosterTracking.positions)){const id=Number(idString),[ox,oy]=origin;const points=[[ox,oy],[ox+80,oy],[ox+80,oy+80],[ox,oy+80]].map(([x,y])=>PosterTracking.project(previous.h,x/1682,y/2378));const xs=points.map(p=>p.x*image.width),ys=points.map(p=>p.y*image.height),span=Math.max(Math.max(...xs)-Math.min(...xs),Math.max(...ys)-Math.min(...ys)),pad=Math.max(25,span*.8),x=Math.max(0,Math.floor(Math.min(...xs)-pad)),y=Math.max(0,Math.floor(Math.min(...ys)-pad)),w=Math.min(image.width-x,Math.ceil(Math.max(...xs)+pad-x)),h=Math.min(image.height-y,Math.ceil(Math.max(...ys)+pad-y));if(w<10||h<10)continue;const scale=Math.min(3,Math.max(1,200/Math.max(w,h)));for(const m of detector.detect(cropScaled(image,x,y,w,h,scale))){if(m.id!==id||m.hammingDistance>3)continue;m.corners=m.corners.map(p=>({x:p.x/scale+x,y:p.y/scale+y}));found.push(m);break;}}return found;}
// A second contrast setting recovers borders softened by focus or photographing a display.
function lowContrastMarkers(image){CV.grayscale(image,detector.grey);CV.adaptiveThreshold(detector.grey,detector.thres,2,2);const contours=CV.findContours(detector.thres,detector.binary);let candidates=detector.findCandidates(contours,image.width*.01,.05,10);candidates=detector.notTooNear(detector.clockwiseCorners(candidates),10);return detector.findMarkers(detector.grey,candidates,80);}
function detect(image){const tracked=trackedRegions(image);if(tracked.length===4)return tracked;if(tracked.length>=3&&PosterTracking.fit(tracked,image.width,image.height).locked)return tracked;const byId=new Map(tracked.map(m=>[m.id,m]));for(const m of detector.detect(image)){if(expected.has(m.id)&&m.hammingDistance<=3&&(!byId.has(m.id)||m.hammingDistance<byId.get(m.id).hammingDistance))byId.set(m.id,m);}let found=[...byId.values()];if(found.length<3){for(const m of lowContrastMarkers(image)){if(expected.has(m.id)&&m.hammingDistance<=3&&!byId.has(m.id))byId.set(m.id,m);}found=[...byId.values()];}if(found.length<4){const regions=[[.48,0,7],[0,0,0],[0,.48,3],[.48,.48,2]];for(const [qx,qy,id] of regions){if(found.some(m=>m.id===id))continue;const x=Math.floor(qx*image.width),y=Math.floor(qy*image.height),w=Math.min(Math.ceil(image.width*.52),image.width-x),h=Math.min(Math.ceil(image.height*.52),image.height-y),scale=1.65;const crop=cropScaled(image,x,y,w,h,scale);for(const m of detector.detect(crop)){if(!expected.has(m.id)||m.hammingDistance>3||found.some(n=>n.id===m.id))continue;m.corners=m.corners.map(p=>({x:p.x/scale+x,y:p.y/scale+y}));found.push(m);}if(found.length===4)break;}}
// Once three corners establish the page, inspect each predicted corner at higher scale.
const provisional=PosterTracking.fit(found,image.width,image.height);
if(provisional.locked){previous={h:provisional.h,width:image.width,height:image.height};const refined=trackedRegions(image);const merged=new Map(found.map(m=>[m.id,m]));for(const m of refined)merged.set(m.id,m);const candidate=[...merged.values()];if(PosterTracking.fit(candidate,image.width,image.height).locked)return candidate;}
return found;}
function markerPose(image){const markers=detect(image);const fitted=PosterTracking.fit(markers,image.width,image.height);previous=fitted.locked?{h:fitted.h,width:image.width,height:image.height}:null;return {...fitted,method:'markers'};}
self.onmessage=e=>{if(!featuresSettled){featuresReady.then(()=>self.onmessage(e));return;}handle(e);};
function handle(e){const {buffer,width,height,session}=e.data;try{const image={data:new Uint8ClampedArray(buffer),width,height};let result=null;
if(features){result=features.locate(PosterFeatures.toGray(image.data,width,height),width,height);if(result.locked)previous={h:result.h,width,height};}
if(!result||!result.locked){const fitted=markerPose(image);if(fitted.locked){features?.seed(fitted.h);result=fitted;}else result={...fitted,method:features?'features':'markers',features:result?.features||0,markers:fitted.count,count:0};}
self.postMessage({session,...result,width,height});}catch(err){self.postMessage({session,locked:false,count:0,reason:'error',message:String(err)});}}
